(1) * l(2) + l(2) ^ 2) ^ 5 - 0.270e3 * xi ^ 8 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 4 * r ^ 2 + 0.11340e5 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * xi ^ 6 * r ^ 4 - 0.255150e6 * xi ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * r ^ 6 + 0.2296350e7 * xi ^ 2 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * r ^ 8 - 0.3444525e7 * r ^ 10) / r ^ 10 / 0.3444525e7 -(r ^ 8 - 0.2e1 / 0.9e1 * xi ^ 2 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * r ^ 6 + 0.2e1 / 0.135e3 * xi ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * r ^ 4 - 0.4e1 / 0.8505e4 * xi ^ 6 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * r ^ 2 + 0.2e1 / 0.229635e6 * xi ^ 8 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 4) * L * xi / r ^ 8; (-(l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * xi ^ 8 * (l(1) + l(2)) ^ 2 + 0.42e2 * (l(1) + l(2)) ^ 2 * xi ^ 6 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * r ^ 2 - 0.945e3 * (l(1) + l(2)) ^ 2 * xi ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * r ^ 4 + 0.8505e4 * (l(1) + l(2)) ^ 2 * xi ^ 2 * r ^ 6 - 0.17010e5 * r ^ 8) / r ^ 8 / 0.17010e5 -(l(1) + l(2)) * (-l(2) + l(1)) * sqrt(0.3e1) * (-(l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * xi ^ 6 / 0.8505e4 + 0.2e1 / 0.405e3 * r ^ 2 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * xi ^ 4 - r ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * xi ^ 2 / 0.9e1 + r ^ 6) * xi ^ 2 / r ^ 8 / 0.6e1 -(l(1) + l(2)) * (r ^ 8 - 0.2e1 / 0.9e1 * xi ^ 2 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * r ^ 6 + 0.2e1 / 0.135e3 * xi ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * r ^ 4 - 0.4e1 / 0.8505e4 * xi ^ 6 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * r ^ 2 + 0.2e1 / 0.229635e6 * xi ^ 8 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 4) * xi / r ^ 9 -(-(l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 3 * xi ^ 6 / 0.8505e4 + 0.2e1 / 0.405e3 * r ^ 2 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) ^ 2 * xi ^ 4 - r ^ 4 * (l(1) ^ 2 + l(1) * l(2) + l(2) ^ 2) * xi ^ 2 / 0.9e1 + r ^ 6) * (l(1) + l(2)) * L * xi ^ 2 / r ^ 7 / 0.2e1; 0 0 0 1;];

